 $mode=$il.DeclareLocal([int]);$normal=$il.DefineLabel();$nonNegative=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields[$(if($write){'WriteMode'}else{'CountMode'})]);$il.Emit([Reflection.Emit.OpCodes]::Stloc,$mode)
 if($write){$skip=$il.DefineLabel();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ble,$skip);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]5);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,42);$il.Emit($(if($abstract.Name -eq 'GetBytes'){[Reflection.Emit.OpCodes]::Stelem_I1}else{[Reflection.Emit.OpCodes]::Stelem_I2}));$il.MarkLabel($skip)}
 $il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_1);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$normal);$il.Emit([Reflection.Emit.OpCodes]::Ldstr,'array callback failure');$il.Emit([Reflection.Emit.OpCodes]::Newobj,[InvalidOperationException].GetConstructor([type[]]@([string])));$il.Emit([Reflection.Emit.OpCodes]::Throw);$il.MarkLabel($normal);$il.Emit([Reflection.Emit.OpCodes]::Ldloc,$mode);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_2);$il.Emit([Reflection.Emit.OpCodes]::Bne_Un,$nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_M1);$il.Emit([Reflection.Emit.OpCodes]::Ret);$il.MarkLabel($nonNegative);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldfld,$fields.Multiplier);$il.Emit([Reflection.Emit.OpCodes]::Mul);$il.Emit([Reflection.Emit.OpCodes]::Ret)
 }else{$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ret)};$builder.DefineMethodOverride($method,$abstract)}

foreach($kind in @(1,2)){[type[]]$parameters=if($kind -eq 1){@([int])}else{@([int],[Text.EncoderFallback],[Text.DecoderFallback])};$constructor=$builder.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,$parameters);$il=$constructor.GetILGenerator();foreach($i in 0..$parameters.Length){$il.Emit([Reflection.Emit.OpCodes]::Ldarg,[int16]$i)};$il.Emit([Reflection.Emit.OpCodes]::Call,[Text.Encoding].GetConstructor([Reflection.BindingFlags]'Instance,NonPublic',$null,$parameters,$null));$il.Emit([Reflection.Emit.OpCodes]::Ret)}

$type=$builder.CreateType();$spoof=$module.DefineType('ReportedCodePageEncoding',[Reflection.TypeAttributes]'Public,Sealed',$type);$ctor=$spoof.DefineConstructor([Reflection.MethodAttributes]::Public,[Reflection.CallingConventions]::Standard,[type[]]@([int]));$il=$ctor.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Call,$type.GetConstructor([type[]]@([int])));$il.Emit([Reflection.Emit.OpCodes]::Ret);$getter=$spoof.DefineMethod('get_CodePage',[Reflection.MethodAttributes]'Public,Virtual,HideBySig,SpecialName',[int],[type[]]@());$il=$getter.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4,65001);$il.Emit([Reflection.Emit.OpCodes]::Ret);$spoof.DefineMethodOverride($getter,[Text.Encoding].GetProperty('CodePage').GetMethod);$spoofType=$spoof.CreateType()
function Failure($e){while(($e -is [Management.Automation.RuntimeException] -or $e -is [Reflection.TargetInvocationException]) -and $null -ne $e.InnerException){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null});message=$e.Message}}
$properties=@('BodyName','EncodingName','HeaderName','WebName','WindowsCodePage','IsBrowserDisplay','IsBrowserSave','IsMailNewsDisplay','IsMailNewsSave','IsSingleByte','CodePage');$rows=[Collections.Generic.List[object]]::new();$constructors=[Collections.Generic.List[object]]::new()
foreach($codePage in @(-1,0,1,42,932,1200,1201,1252,12000,12001,20127,28591,65000,65001,65535,65536,2147483647)){foreach($reported in @($false,$true)){$owner=$null;try{$owner=$(if($reported){$spoofType}else{$type}).GetConstructor([type[]]@([int])).Invoke([object[]]@([int]$codePage));$result=[ordered]@{ok=$true}}catch{$result=Failure $_.Exception};$constructors.Add([ordered]@{codePage=$codePage;reportedOverride=$reported;result=$result});if($result.ok){foreach($property in $properties){try{$info=[Text.Encoding].GetProperty($property);$value=$info.GetMethod.Invoke($owner,[object[]]@());$result=[ordered]@{ok=$true;value=$value;valueType=$info.PropertyType.FullName}}catch{$result=Failure $_.Exception};$rows.Add([ordered]@{codePage=$codePage;reportedOverride=$reported;property=$property;result=$result})}}}}
$exceptionConstructors=[Collections.Generic.List[object]]::new();foreach($kind in 0..2){foreach($messageCase in 0..2){if($kind -eq 0 -and $messageCase -ne 0){continue};$message=$null;if($messageCase -eq 1){$message=''}elseif($messageCase -eq 2){$message='owned'};$inner=[Exception]::new('inner');$failure=switch($kind){0{[NotSupportedException]::new()}1{[NotSupportedException].GetConstructor([type[]]@([string])).Invoke([object[]]@($message))}2{[NotSupportedException].GetConstructor([type[]]@([string],[Exception])).Invoke([object[]]@($message,$inner))}};$exceptionConstructors.Add([ordered]@{kind=$kind;message=$message;actualMessage=$failure.Message;hResult=$failure.HResult;innerSame=[object]::ReferenceEquals($failure.InnerException,$inner);fullName=$failure.GetType().FullName;baseType=$failure.GetType().BaseType.FullName})}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();referenceHostEncodingIds=[int[]]@([Text.Encoding]::GetEncodings()|ForEach-Object CodePage);constructors=$constructors.ToArray();rows=$rows.ToArray();exceptionConstructors=$exceptionConstructors.ToArray();qualification='SELECTED_GENERIC_ENCODING_METADATA_AND_NOTSUPPORTED_CONSTRUCTORS_ONLY; BASE_METADATA_NOT_PROVIDER_CODEC_AVAILABILITY_LOCALIZATION_FULL_METADATA_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS generic Encoding metadata: $($rows.Count) property rows, $($constructors.Count) constructors"
